using System.Text;

namespace CthExtract.Oodle.Tests.Synth;

/// <summary>Deterministic test inputs generated by our own code (no third-party corpora).</summary>
internal static class SynthData
{
    public static readonly string[] Kinds = { "text", "records", "runs", "random", "sine16", "mixed", "sparse", "counter", "alpha4", "zeros" };

    static readonly string[] Words =
    {
        "the", "battle", "bus", "drops", "over", "a", "blocky", "world", "and", "master", "chief", "glides", "toward",
        "chest", "loot", "shield", "potion", "infernus", "sultan", "blista", "wanted", "stars", "police", "siren",
        "creeper", "zombie", "skeleton", "assault", "rifle", "battle", "rifle", "needler", "plasma", "pistol", "bandage",
        "med", "kit", "chug", "jug", "energy", "recharge", "redstone", "diamond", "pickaxe", "village", "ocean", "biome",
    };

    public static byte[] Make(string kind, int size, int seed)
    {
        var rng = new Random(seed);
        var d = new byte[size];
        switch (kind)
        {
            case "text":
            {
                var sb = new StringBuilder(size + 64);
                while (sb.Length < size)
                {
                    sb.Append(Words[(int)(Math.Pow(rng.NextDouble(), 2) * Words.Length)]);
                    sb.Append(rng.Next(12) == 0 ? ".\n" : rng.Next(8) == 0 ? ", " : " ");
                    if (rng.Next(40) == 0) sb.Append(rng.Next(100000));
                }
                Encoding.ASCII.GetBytes(sb.ToString(0, size), d);
                break;
            }
            case "records":
                // little-endian structs: id, slowly changing position, flags, a name from a small table
                for (int i = 0; i + 16 <= size; i += 16)
                {
                    BitConverter.TryWriteBytes(d.AsSpan(i), i / 16);
                    BitConverter.TryWriteBytes(d.AsSpan(i + 4), (float)Math.Sin(i * 0.001) * 100f);
                    d[i + 8] = (byte)(rng.Next(4) == 0 ? 1 : 0);
                    Encoding.ASCII.GetBytes(Words[(i / 16) % 7].PadRight(7).AsSpan(0, 7), d.AsSpan(i + 9));
                }
                break;
            case "runs":
                for (int i = 0; i < size;)
                {
                    int r = rng.Next(4) == 0 ? rng.Next(1, 600) : rng.Next(1, 12);
                    byte v = (byte)(rng.Next(3) == 0 ? rng.Next(256) : rng.Next(4));
                    for (int k = 0; k < r && i < size; k++) d[i++] = v;
                }
                break;
            case "random":
                rng.NextBytes(d);
                break;
            case "sine16":
                for (int i = 0; i + 1 < size; i += 2)
                {
                    short s = (short)(12000 * Math.Sin(i / 37.0) + rng.Next(-30, 30));
                    d[i] = (byte)s; d[i + 1] = (byte)(s >> 8);
                }
                break;
            case "mixed":
            {
                var t = Make("text", size, seed + 1);
                var r = Make("random", size, seed + 2);
                var c = Make("records", size, seed + 3);
                for (int i = 0; i < size; i += 4096)
                {
                    var src = ((i / 4096) % 3) switch { 0 => t, 1 => r, _ => c };
                    Array.Copy(src, i, d, i, Math.Min(4096, size - i));
                }
                break;
            }
            case "sparse":
                for (int i = 0; i < size; i++)
                    d[i] = rng.Next(30) == 0 ? (byte)rng.Next(256) : (byte)0;
                break;
            case "counter":
                for (int i = 0; i < size; i++)
                    d[i] = (byte)(i * 7 + (i >> 9));
                break;
            case "alpha4":
                for (int i = 0; i < size; i++)
                    d[i] = (byte)"ACGT"[rng.Next(4)];
                break;
            case "zeros":
                break;
            default:
                throw new ArgumentException(kind);
        }
        return d;
    }
}
